<?php
namespace App\Controller;
use App\Catalog\CatalogService; use App\Entity\User; use App\Repository\LibraryEntryRepository; use App\Repository\SeriesRepository; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route;
class CatalogController extends AbstractController { #[Route('/catalogue',name:'app_catalog')] public function index(Request $request,CatalogService $catalog):Response{$q=trim((string)$request->query->get('q',''));return $this->render('catalog/index.html.twig',['query'=>$q,'results'=>$q!==''?$catalog->search($q):[]]);} #[Route('/catalogue/tvmaze/{id}',name:'app_catalog_import',requirements:['id'=>'\d+'])] public function import(string $id,CatalogService $catalog):Response{$series=$catalog->import($id);return $this->redirectToRoute('app_series_show',['id'=>$series->getId()]);} #[Route('/series/{id}',name:'app_series_show')] public function show(int $id,SeriesRepository $series,LibraryEntryRepository $entries):Response{$show=$series->find($id)??throw $this->createNotFoundException();$user=$this->getUser();return $this->render('catalog/show.html.twig',['series'=>$show,'entry'=>$user instanceof User?$entries->findForUserAndSeries($user,$show):null]);} }
